1	/**
2	 * workspace-scope.ts — walk to the root issue whose workspace a run shares.
3	 *
4	 * The I/O half of `domain/work/workspace.ts`'s `workspaceScope`, which holds the rule.
5	 * Here is the walking: one hop at a time through `parentIssueOf`, and for a pull
6	 * request one extra hop first, because a pull request's link to its issue is the
7	 * `atomaton:parent-issue` tag rather than a sub-issue relationship.
8	 */
9	import { readPullRequest } from "./pull-request.ts";
10	import { parentChain, parentIssueOf, type ParentIssue } from "./parent-issue.ts";
11	import { PARENT_ISSUE_TAG } from "./tags.ts";
12	import { workspaceScope, type WorkspaceScope } from "../../domain/work/workspace.ts";
