14	function log(message: string): void {
15	  console.error(`[atomaton-workspace] ${message}`);
16	}
17	
18	/**
19	 * The issue a pull request was opened for, or undefined when it says nothing.
20	 *
21	 * One field of the pull request, read through `pull-request.ts` like every other
22	 * question about a pull request. The read is the same; only what a failure means is
23	 * this module's, and it is `undefined` — a pull request nobody could read gets a
24	 * private workspace rather than borrowing one, which is the direction
25	 * `domain/work/workspace.ts` argues for.
26	 */
27	function issueOfPullRequest(repo: string, number: number): number | undefined {
28	  const read = readPullRequest<{ body?: string }>(repo, number, "body");
29	  if (!read.known) {
30	    log(`WARN ${read.why}`);
31	    return undefined;
32	  }
33	  // Prose only, like every other read of a GitHub body (#304): a pull request body
34	  // quoting the tag inside a fenced sample names no parent.
35	  return PARENT_ISSUE_TAG.readProse(read.value.body ?? "");
36	}
