46	export function resolveWorkspaceScope(repo: string, type: string, number: string | number): WorkspaceScope {
47	  const target = Number(number);
48	  if (!Number.isFinite(target) || target <= 0) {
49	    return workspaceScope(number, [], `"${number}" is not an issue or pull request number`);
50	  }
51	
52	  const chain: number[] = [];
53	  let start = target;
54	
55	  if (type === "pr") {
56	    const issue = issueOfPullRequest(repo, target);
57	    if (issue === undefined) {
58	      // A pull request with no issue tag is its own root. Ordinary for one a person
59	      // opened, so it is not a failure -- but it also means no sharing, which is
60	      // why it is said out loud.
61	      log(`#${target} names no parent issue; its workspace is its own`);
62	      return workspaceScope(number, []);
63	    }
64	    chain.push(issue);
65	    start = issue;
66	  }
67	
68	  // The walk is `parentChain`'s, so the depth limit and the cycle guard are the same
69	  // ones `notify.ts` uses. It used to be written out here with its own `MAX_HOPS = 6`
70	  // and a comment claiming it matched `notify.ts`, which had 10.
71	  for (const hop of parentChain(start, (current) => ({ data: undefined, parent: parentIssueOf(repo, current) }))) {
72	    if (!hop.parent.known) {
73	      // Everything read so far still counts. A chain that broke three hops up is
74	      // more precise than falling all the way back to the target, and the tests
75	      // pin that: the root reached is the answer, not the failure.
76	      return workspaceScope(number, chain, chain.length > 0 ? "" : hop.parent.why);
77	    }
78	    if (hop.parent.parent === 0) break;
79	    chain.push(hop.parent.parent);
80	  }
81	
82	  const scope = workspaceScope(number, chain);
83	  if (!scope.resolved) log(`WARN ${scope.why}; using this target's own workspace`);
84	  else if (scope.rootIssue !== String(number)) log(`sharing issue #${scope.rootIssue}'s workspace`);
85	  return scope;
86	}
